pub fn verr(msg: impl Into<String>) -> PyError {
    PyError { kind: "ValueError", msg: msg.into() }
}

pub fn oserr(msg: impl Into<String>) -> PyError {
    PyError { kind: "OSError", msg: msg.into() }
}

