fn load_yaml(path: &Path) -> Result<Value, PyError> {
    let text = std::fs::read_to_string(path).map_err(|e| io_to_py(&e))?;
    let v: Value = serde_yaml::from_str(&text)
        .map_err(|e| super::jsonc::jsonerr(format!("{}", e)))?;
    Ok(v)
}

pub fn load_atoms(yaml_path: &Path) -> Result<Value, PyError> {
    let raw = load_yaml(yaml_path)?;
    Ok(raw.get("atoms").cloned().unwrap_or(Value::Null))
}

pub fn load_paradigms(yaml_path: &Path) -> Result<BTreeMap<String, Value>, PyError> {
    let raw = load_yaml(yaml_path)?;
    let mut out = BTreeMap::new();
    if let Some(list) = raw.get("paradigms").and_then(|v| v.as_array()) {
        for p in list {
            if let Some(id) = p.get("id").and_then(|v| v.as_str()) {
                out.insert(id.to_string(), p.clone());
            }
        }
    }
    Ok(out)
}

pub fn validate_paradigm(
    paradigm: &Value,
    atoms: &Value,
    available_validators: &[String],
) -> Vec<String> {
    let mut errors: Vec<String> = Vec::new();
    let pid = paradigm.get("id").and_then(|v| v.as_str()).unwrap_or_default().to_string();

    // 1. 引用完整性：所有 atoms 必须在 atom.yaml 里存在
    if let Some(list) = paradigm.get("atoms").and_then(|v| v.as_array()) {
        for atom_name in list {
            let name = atom_name.as_str().unwrap_or_default();
            if atoms.get(name).is_none() {
                errors.push(format!(
                    "paradigm '{}': atom '{}' 不在 atom.yaml 中",
                    pid, name
                ));
            }
        }
        // 2. validators.func 必须在 VALIDATORS 里（只检查 facetor_independent 的 directions）
        for atom_name in list {
            let name = atom_name.as_str().unwrap_or_default();
            if let Some(atom_cfg) = atoms.get(name) {
                if let Some(directions) = atom_cfg.get("directions").and_then(|v| v.as_array()) {
                    for direction in directions {
                        if let Some(func_name) = direction.get("validator").and_then(|v| v.as_str()) {
                            if !available_validators.contains(&func_name.to_string()) {
                                errors.push(format!(
                                    "paradigm '{}': validator '{}' 不在 VALIDATORS 中",
                                    pid, func_name
                                ));
                            }
                        }
                    }
                }
            }
        }
    }

    // 3. single_round_explore 特殊检查：composition 必须是 parallel
    if pid == "single_round_explore" {
        let composition = paradigm.get("composition").and_then(|v| v.as_array()).cloned();
        match composition {
            None => errors.push(format!("paradigm '{}': composition 为空", pid)),
            Some(c) => {
                if c.is_empty() {
                    errors.push(format!("paradigm '{}': composition 为空", pid));
                } else {
                    let step = &c[0];
                    let has_parallel = step.get("parallel").is_some();
                    if !has_parallel {
                        errors.push(format!(
                            "paradigm '{}': composition 第一步必须是 parallel",
                            pid
                        ));
                    }
                }
            }
        }
    }
    errors
}

pub fn validate_all(
    atom_yaml: &Path,
    chain_yaml: &Path,
    available_validators: &[String],
) -> Result<BTreeMap<String, Vec<String>>, PyError> {
    let atoms = load_atoms(atom_yaml)?;
    let paradigms = load_paradigms(chain_yaml)?;
    let mut result = BTreeMap::new();
    for (pid, paradigm) in &paradigms {
        result.insert(pid.clone(), validate_paradigm(paradigm, &atoms, available_validators));
    }
    Ok(result)
}

fn require_counts(k: i64, n: i64) -> Result<(), PyError> {
    if n < 0 {
        return Err(verr(format!("n 须非负，实际为 {}", n)));
    }
    if k < 0 || k > n {
        return Err(verr(format!("须 0 <= k <= n，实际 k = {}, n = {}", k, n)));
    }
    Ok(())
}

fn require_probability(value: f64, name: &str, open_interval: bool) -> Result<f64, PyError> {
    if open_interval {
        if !(0.0 < value && value < 1.0) {
            return Err(verr(format!("{} 须落在开区间 (0, 1)，实际为 {}", name, value)));
        }
    } else if !(0.0 <= value && value <= 1.0) {
        return Err(verr(format!("{} 须落在闭区间 [0, 1]，实际为 {}", name, value)));
    }
    Ok(value)
}

fn require_p_values(p_values: &[Value]) -> Result<Vec<f64>, PyError> {
    if p_values.is_empty() {
        return Err(verr("p_values 须非空"));
    }
    let mut out = Vec::with_capacity(p_values.len());
    for (i, item) in p_values.iter().enumerate() {
        let v = item.as_f64().ok_or_else(|| verr(format!("p_values[{}] 须为实数", i)))?;
        out.push(require_probability(v, &format!("p_values[{}]", i), false)?);
    }
    Ok(out)
}

fn log_binom(n: i64, j: i64) -> f64 {
    lgamma((n + 1) as f64) - lgamma((j + 1) as f64) - lgamma((n - j + 1) as f64)
}

fn binom_upper_tail(k: i64, n: i64, p: f64) -> f64 {
    if k == 0 {
        return 1.0;
    }
    let log_p = p.ln();
    let log_q = (1.0 - p).ln();
    let terms: Vec<f64> = (k..=n)
        .map(|j| (log_binom(n, j) + j as f64 * log_p + (n - j) as f64 * log_q).exp())
        .collect();
    fsum(&terms).min(1.0)
}

pub fn binomial_test_pvalue(k: i64, n: i64, p_h0: f64) -> Result<f64, PyError> {
    require_counts(k, n)?;
    let p = require_probability(p_h0, "p_h0", true)?;
    Ok(binom_upper_tail(k, n, p))
}

pub fn boundary_test_pvalue(k: i64, n: i64, p_h0: f64) -> Result<f64, PyError> {
    require_counts(k, n)?;
    let p = require_probability(p_h0, "p_h0", true)?;
    Ok(binom_upper_tail(k, n, p))
}

pub fn bonferroni_correction(p_values: &[Value], alpha: f64) -> Result<Vec<f64>, PyError> {
    let ps = require_p_values(p_values)?;
    require_probability(alpha, "alpha", true)?;
    let m = ps.len();
    Ok(ps.iter().map(|p| (p * m as f64).min(1.0)).collect())
}

pub fn bh_fdr(p_values: &[Value], alpha: f64) -> Result<Vec<f64>, PyError> {
    let ps = require_p_values(p_values)?;
    require_probability(alpha, "alpha", true)?;
    let m = ps.len();
    let mut order: Vec<usize> = (0..m).collect();
    order.sort_by(|a, b| ps[*a].partial_cmp(&ps[*b]).unwrap_or(std::cmp::Ordering::Equal));
    let mut adjusted = vec![0.0f64; m];
    let mut running_min = 1.0f64;
    for rank in (1..=m).rev() {
        let idx = order[rank - 1];
        let candidate = (m as f64 / rank as f64) * ps[idx];
        if candidate < running_min {
            running_min = candidate;
        }
        adjusted[idx] = running_min.min(1.0);
    }
    Ok(adjusted)
}

pub fn statistical_power(n: i64, p_h0: f64, p_h1: f64, alpha: f64) -> Result<f64, PyError> {
    if n < 1 {
        return Err(verr(format!("n 须为正整数，实际为 {}", n)));
    }
    let p0 = require_probability(p_h0, "p_h0", true)?;
    let p1 = require_probability(p_h1, "p_h1", true)?;
    let a = require_probability(alpha, "alpha", true)?;

    let log_p0 = p0.ln();
    let log_q0 = (1.0 - p0).ln();
    let terms0: Vec<f64> = (0..=n)
        .map(|j| (log_binom(n, j) + j as f64 * log_p0 + (n - j) as f64 * log_q0).exp())
        .collect();

    let mut k_star = n + 1;
    let mut suffix = 0.0f64;
    for k in (0..=n).rev() {
        suffix += terms0[k as usize];
        if suffix <= a {
            k_star = k;
        } else {
            break;
        }
    }
    if k_star == n + 1 {
        return Ok(0.0);
    }

    let log_p1 = p1.ln();
    let log_q1 = (1.0 - p1).ln();
    let terms1: Vec<f64> = (k_star..=n)
        .map(|j| (log_binom(n, j) + j as f64 * log_p1 + (n - j) as f64 * log_q1).exp())
        .collect();
    Ok(fsum(&terms1).min(1.0))
}

fn validate_vector(values: &[Value], name: &str) -> Result<Vec<f64>, PyError> {
    if values.is_empty() {
        return Err(verr(format!("{}: 输入序列为空，至少需要一个分量", name)));
    }
    let mut checked = Vec::with_capacity(values.len());
    for (index, item) in values.iter().enumerate() {
        let v = item.as_f64().ok_or_else(|| {
            verr(format!(
                "{}[{}]: 元素类型 {} 不是实数",
                name,
                index,
                py_type(item)
            ))
        })?;
        if v < 0.0 {
            return Err(verr(format!("{}[{}]: 元素为负数 {}", name, index, v)));
        }
        checked.push(v);
    }
    Ok(checked)
}

fn py_type(v: &Value) -> &'static str {
    match v {
        Value::String(_) => "str",
        Value::Bool(_) => "bool",
        Value::Number(_) => "float",
        Value::Null => "NoneType",
        _ => "object",
    }
}

fn normalize(vector: &[f64], name: &str) -> Result<Vec<f64>, PyError> {
    let total = fsum(vector);
    if total <= 0.0 {
        return Err(verr(format!("{}: 全零向量无法归一化为概率分布", name)));
    }
    Ok(vector.iter().map(|x| x / total).collect())
}

fn validated_pair(p: &[Value], q: &[Value]) -> Result<(Vec<f64>, Vec<f64>), PyError> {
    let vp = validate_vector(p, "p")?;
    let vq = validate_vector(q, "q")?;
    if vp.len() != vq.len() {
        return Err(verr(format!(
            "p 与 q 长度不等：len(p)={} 对 len(q)={}",
            vp.len(),
            vq.len()
        )));
    }
    Ok((vp, vq))
}

pub fn hellinger_distance(p: &[Value], q: &[Value]) -> Result<f64, PyError> {
    let (vp, vq) = validated_pair(p, q)?;
    let pn = normalize(&vp, "p")?;
    let qn = normalize(&vq, "q")?;
    let terms: Vec<f64> = pn
        .iter()
        .zip(qn.iter())
        .map(|(a, b)| (a.sqrt() - b.sqrt()).powi(2))
        .collect();
    Ok(fsum(&terms).sqrt() / 2.0f64.sqrt())
}

pub fn tv_distance(p: &[Value], q: &[Value]) -> Result<f64, PyError> {
    let (vp, vq) = validated_pair(p, q)?;
    let pn = normalize(&vp, "p")?;
    let qn = normalize(&vq, "q")?;
    let terms: Vec<f64> = pn.iter().zip(qn.iter()).map(|(a, b)| (a - b).abs()).collect();
    Ok(0.5 * fsum(&terms))
}

pub fn js_divergence(p: &[Value], q: &[Value]) -> Result<f64, PyError> {
    let (vp, vq) = validated_pair(p, q)?;
    let pn = normalize(&vp, "p")?;
    let qn = normalize(&vq, "q")?;
    let mut total = 0.0f64;
    for (a, b) in pn.iter().zip(qn.iter()) {
        let m = 0.5 * (a + b);
        if *a > 0.0 {
            total += 0.5 * a * (a / m).ln();
        }
        if *b > 0.0 {
            total += 0.5 * b * (b / m).ln();
        }
    }
    Ok(total)
}

pub fn generalized_jaccard(p: &[Value], q: &[Value]) -> Result<f64, PyError> {
    let (va, vb) = validated_pair(p, q)?;
    let denominator = fsum(&va.iter().zip(vb.iter()).map(|(x, y)| x.max(*y)).collect::<Vec<_>>());
    if denominator == 0.0 {
        return Err(verr("p 与 q 全零，Σmax = 0，广义 Jaccard 无定义"));
    }
    let numerator = fsum(&va.iter().zip(vb.iter()).map(|(x, y)| x.min(*y)).collect::<Vec<_>>());
    Ok(numerator / denominator)
}

