fn target_in_domain(dom: &sih_engine::scrutinator::rule::DomainSpec, path: &str) -> bool {
    let abs = std::fs::canonicalize(path)
        .ok()
        .and_then(|p| p.to_str().map(String::from))
        .unwrap_or_else(|| path.to_string());
    if sih_engine::scrutinator::rule::domain_match(dom, &abs)
        || sih_engine::scrutinator::rule::domain_match(dom, path)
    {
        return true;
    }
    match sih_engine::scrutinator::rule::discover_workspace_root(&abs) {
        Some(root) => sih_engine::scrutinator::rule::domain_match_rooted(dom, &root, &abs),
        None => false,
    }
}

struct Parsed {
    /// 每个 --pack 的值，按出现顺序
    pack_names: Vec<String>,
    /// 每个 --target 的值（旗标别名），按出现顺序
    flag_targets: Vec<String>,
    /// 位置参数目标，按出现顺序（--pack 旗标值之后、非 -- 开头的参数）
    positional_targets: Vec<String>,
}

fn parse_args(args: &[String]) -> Parsed {
    let mut pack_names: Vec<String> = Vec::new();
    let mut flag_targets: Vec<String> = Vec::new();
    let mut positional_targets: Vec<String> = Vec::new();
    let mut i = 0;
    while i < args.len() {
        if args[i] == "--pack" {
            if i + 1 < args.len() {
                pack_names.push(args[i + 1].clone());
                i += 2;
            } else {
                i += 1;
            }
        } else if args[i] == "--target" {
            if i + 1 < args.len() {
                flag_targets.push(args[i + 1].clone());
                i += 2;
            } else {
                i += 1;
            }
        } else if args[i].starts_with("--") {
            // 未知旗标：跳过旗标与其值（若 value 不以 -- 开头则认为是旗标值）
            if i + 1 < args.len() && !args[i + 1].starts_with("--") {
                i += 2;
            } else {
                i += 1;
            }
        } else {
            // 位置参数
            positional_targets.push(args[i].clone());
            i += 1;
        }
    }
    Parsed {
        pack_names,
        flag_targets,
        positional_targets,
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    // 跳过 argv[0]（binary 名）
    let parsed = parse_args(&args[1..]);

    // 装载：--pack 可重复，未传走默认三包全量
    let pack_names: Vec<String> = if !parsed.pack_names.is_empty() {
        parsed.pack_names.clone()
    } else {
        // 未传 --pack = 走默认三包（决定空载形与否：传 --pack 但取空值才是空载）
        PACK_NAMES.iter().map(|s| s.to_string()).collect()
    };

    // 缺包检查：未知名包产退出码 2
    let pack_refs: Vec<&str> = pack_names.iter().map(|s| s.as_str()).collect();
    let packs_data = match load_packs(&pack_refs) {
        Ok(v) => v,
        Err(e) => {
            emit(
                serde_json::to_value(&CliOutput { error: e }).unwrap(),
                2,
            );
        }
    };

    // 目标收集：旗标 target + 位置参数 target 按出现顺序取并集
    // 这里为了语义最简：合并去重但保持首次出现顺序
    let mut target_paths: Vec<String> = Vec::new();
    let mut seen = std::collections::HashSet::new();
    for t in &parsed.flag_targets {
        if seen.insert(t.clone()) {
            target_paths.push(t.clone());
        }
    }
    for t in &parsed.positional_targets {
        if seen.insert(t.clone()) {
            target_paths.push(t.clone());
        }
    }

    // 空载形：未传任何 target（包括位置参数），产 packs=[] 报告、findings=[]、退出码 0
    if target_paths.is_empty() {
        let report = render_report(&packs_data, &[], &[]);
        emit(serde_json::to_value(&report).unwrap(), 0);
    }

    // 域判定：每个 target 必须命中至少一个包域；都未命中则产 domain_mismatch 并退出码 2
    let mut all_in_domain = true;
    let mut domain_mismatches: Vec<String> = Vec::new();
    for path in &target_paths {
        let in_any = packs_data
            .iter()
            .any(|(_, dom, _)| target_in_domain(dom, path));
        if !in_any {
            all_in_domain = false;
            domain_mismatches.push(path.clone());
        }
    }
    if !all_in_domain {
        let mut packs_map = serde_json::Map::new();
        for (name, dom, _) in &packs_data {
            packs_map.insert(
                name.clone(),
                serde_json::json!({"include": dom.include, "exclude": dom.exclude}),
            );
        }
        let out = serde_json::json!({
            "error": "目标不在任何已加载规则包声明的治理域内",
            "unmatched_targets": domain_mismatches,
            "packs": serde_json::Value::Object(packs_map),
        });
        emit(out, 2);
    }

    // 加载目标文本/JSON
    let mut targets: Vec<(String, Option<String>)> = Vec::new();
    for path in &target_paths {
        let text = read_text(path);
        // 目标 path 用绝对路径，与工具件 Python `str(pathlib.Path(target).resolve())` 对表
        let abs_path = std::fs::canonicalize(path)
            .ok()
            .and_then(|p| p.to_str().map(String::from))
            .unwrap_or_else(|| path.clone());
        targets.push((abs_path, text));
    }

    // 跑规则：每个 pack 只跑在它域内的 target
    let mut findings = Vec::new();
    for (pack_name, dom, rules) in &packs_data {
        for (path, text_opt) in &targets {
            if let Some(text) = text_opt {
                // 域内判定：target 在 pack 域内才跑（scrutpath-solo 起含根锚定工地形）
                let in_domain = target_in_domain(dom, path);
                if !in_domain {
                    continue;
                }
                // finding 的 path 字段填绝对路径，与工具件 Python `str(path)` 行为对表
                // （targets 已按 canonicalize 绝对化，此处即 targets 的 path 本形）
                let finding_path = path.clone();
                // 判断材料轴：manifest 标 json 走 json 规则，否则 text
                let manifest = sih_engine::scrutinator::asset::manifest(pack_name);
                let is_json_pack = manifest.contains("material = \"json\"")
                    || manifest.contains("material=\"json\"");
                if is_json_pack {
                    if let Ok(v) = serde_json::from_str::<serde_json::Value>(text) {
                        findings.extend(run_rules_on_json(pack_name, rules, &v, &finding_path));
                    }
                } else {
                    findings.extend(run_rules_on_text(pack_name, rules, text, &finding_path));
                }
            }
        }
    }

    let report = render_report(&packs_data, &targets, &findings);
    let code = if report.findings.is_empty() { 0 } else { 1 };
    emit(serde_json::to_value(&report).unwrap(), code);
}

fn emit(value: serde_json::Value, code: i32) -> ! {
    println!("{}", serde_json::to_string_pretty(&value).unwrap());
    exit(code)
}

fn read_args() -> Vec<(String, String)> {
    let args: Vec<String> = std::env::args().collect();
    let mut opts: Vec<(String, String)> = Vec::new();
    let mut i = 2;
    while i < args.len() {
        if args[i].starts_with("--") && i + 1 < args.len() {
            opts.push((
                args[i].trim_start_matches('-').to_string(),
                args[i + 1].clone(),
            ));
            i += 2;
        } else {
            i += 1;
        }
    }
    opts
}

fn collect_trails(opts: &[(String, String)]) -> Vec<String> {
    opts.iter()
        .filter(|(k, _)| k == "trail")
        .map(|(_, v)| v.clone())
        .collect()
}

fn first_value<'a>(opts: &'a [(String, String)], key: &str) -> Option<&'a str> {
    for (k, v) in opts {
        if k == key {
            return Some(v.as_str());
        }
    }
    None
}

fn load_trails_or_die(trails: &[String]) -> Vec<sih_engine::event_stream::event::Event> {
    if trails.is_empty() {
        emit(json!({"error": "缺 --trail"}), 2);
    }
    let mut all: Vec<sih_engine::event_stream::event::Event> = Vec::new();
    for t in trails {
        let path = PathBuf::from(t);
        if !path.exists() {
            emit(json!({"error": "trail 不存在", "path": t}), 2);
        }
        match load_events(path.as_path()) {
            Ok(mut evs) => all.append(&mut evs),
            Err(e) => emit(json!({"error": format!("trail 不可读 {e:?}"), "path": t}), 2),
        }
    }
    all
}

fn attach_trail_info(payload: &mut serde_json::Value, trails: &[String]) {
    if let Some(first) = trails.first() {
        payload["trail"] = serde_json::Value::String(first.clone());
    }
    if trails.len() > 1 {
        payload["trails"] = serde_json::Value::Array(
            trails
                .iter()
                .map(|t| serde_json::Value::String(t.clone()))
                .collect(),
        );
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let cmd = args.get(1).map(|s| s.as_str()).unwrap_or("");
    let opts = read_args();
    let trails = collect_trails(&opts);

    match cmd {
        "alarms" => {
            let events = load_trails_or_die(&trails);
            let view = alarms_view(&events);
            let code = view.exit_code_suggested;
            let mut payload = serde_json::to_value(&view).unwrap();
            attach_trail_info(&mut payload, &trails);
            emit(payload, code);
        }
        "heartbeat" => {
            let events = load_trails_or_die(&trails);
            let Some(at) = first_value(&opts, "at") else {
                emit(json!({"error": "缺 --at YYYY-MM-DD"}), 2)
            };
            let date = match NaiveDate::parse_from_str(at, "%Y-%m-%d") {
                Ok(d) => d,
                Err(e) => emit(json!({"error": format!("--at 解析失败 {e}")}), 2),
            };
            let view = heartbeat_view(&events, date);
            let mut payload = serde_json::to_value(&view).unwrap();
            attach_trail_info(&mut payload, &trails);
            emit(payload, 0);
        }
        "settle" => {
            let events = load_trails_or_die(&trails);
            let Some(date_str) = first_value(&opts, "date") else {
                emit(json!({"error": "缺 --date YYYY-MM-DD"}), 2)
            };
            let date = match NaiveDate::parse_from_str(date_str, "%Y-%m-%d") {
                Ok(d) => d,
                Err(e) => emit(json!({"error": format!("--date 解析失败 {e}")}), 2),
            };
            // 在泊复检名单 = heartbeat 配对产出，复用同一参照日
            let hb = heartbeat_view(&events, date);
            let view = settle_view(&events, date, hb.parking);
            let mut payload = serde_json::to_value(&view).unwrap();
            attach_trail_info(&mut payload, &trails);
            emit(payload, 0);
        }
        _ => emit(
            json!({"error": "用法 viewer <alarms|heartbeat|settle> --trail <路径> [--at YYYY-MM-DD | --date YYYY-MM-DD]"}),
            2,
        ),
    }
}

