fn temp_trail(tag: &str) -> PathBuf {
        let dir = std::env::temp_dir().join(format!("chainstamp-{tag}-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        dir.join("trail.ndjson")
