        std::fs::write(
            &sessions,
            "{\"event\":\"issued\",\"session_id\":\"sessA\"}\n{\"event\":\"revoked\",\"session_id\":\"sessA\"}\n",
        )
        .unwrap();
        assert!(matches!(
            check_session(&sessions, Some("sessA"), None),
