        let date = NaiveDate::from_ymd_opt(2026, 1, 8).unwrap();
        let day_start = date.and_hms_opt(0, 0, 0).unwrap().and_utc().timestamp();
        // 用含 details.entry_id 与 ttl_days 的真实停泊事件
