        e1.details = Some(json!({"entry_id":"pk-100","title":"settle-test","ttl_days":7}));
        let events = vec![e1];
        let hb = heartbeat_view(&events, date);
        let view = settle_view(&events, date, hb.parking.clone());
        assert_eq!(view.parking_review.len(), 1);
    }

